/* Mobile-first base (375px-639px) */
.chat-container {
  max-width: 100%;
  padding: 0 16px;
}

.confirmation-card {
  padding: 20px;
  font-size: 16px;
}

/* Tablet (640px-1023px) */
@media (min-width: 640px) {
  .chat-container {
    max-width: 600px;
    margin: 0 auto;
  }

  .confirmation-card {
    padding: 24px;
    font-size: 16px;
  }
}

/* Desktop (1024px+) */
@media (min-width: 1024px) {
  .chat-container {
    max-width: 700px;
    margin: 0 auto;
  }

  .message-spacing {
    margin-bottom: 40px; /* More generous on desktop */
  }
}

/* ✅ Mobile-first approach (default styles for mobile) */
.button {
  width: 100%;              /* Full-width on mobile */
  padding: 0.75rem 1rem;   /* 12px 16px */
}

@media (min-width: 640px) {
  .button {
    width: auto;            /* Auto-width on desktop */
    padding: 0.75rem 2rem;  /* 12px 32px */
  }
}

// ✅ Minimum 44x44px touch targets
<button className="min-h-[44px] min-w-[44px] p-3">
  Submit
</button>

// ✅ Increase touch area with invisible padding on mobile
<button className="p-3 sm:p-2">
  {/* More padding on mobile */}
</button>

// ✅ Keyboard event handling
<div
  role="button"
  tabIndex={0}
  onClick={handleClick}
  onKeyDown={(e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleClick();
    }
  }}
>
  Suggestion chip
</div>

// ✅ Focus management
useEffect(() => {
  if (responseComplete) {
    inputRef.current?.focus(); // Return focus after response
  }
}, [responseComplete]);

/* ✅ Visible focus indicators (never remove outlines!) */
button:focus-visible {
  outline: 2px solid hsl(142 71% 45%); /* emerald-500 */
  outline-offset: 2px;
}

/* ❌ Never do this */
button:focus {
  outline: none; /* Removes keyboard navigation visibility */
}

/* ✅ Support Windows High Contrast Mode */
@media (prefers-contrast: high) {
  .button {
    border: 2px solid currentColor; /* Ensures visibility */
  }
}

/* ✅ Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

// ✅ Associate error messages with fields
<div>
  <label htmlFor="input">Message</label>
  <input
    id="input"
    aria-invalid={hasError}
    aria-describedby={hasError ? "error-message" : undefined}
  />
  {hasError && (
    <div id="error-message" role="alert">
      {errorMessage}
    </div>
  )}
</div>
